/** The themes drawn here: the lesson themes, idea, and unit (the grand stop). */
export const STOP_THEMES = Object.keys(STOPS);

/** How far a press moves .lx-stop-top, in units of the 96 box. */
export const STOP_PRESS = [1.13, 1.3];

let copies = 0;
/** A stop as an inline <svg>, its own copy with its own ids. size: px; label: what it means, when nothing beside it says so. */
export function stopArt(theme, { size = 84, label = "" } = {}) {
  const svg = document.createElementNS(SVG_NS, "svg");
  svg.setAttribute("viewBox", "0 0 96 96");
  svg.setAttribute("width", String(size));
  svg.setAttribute("height", String(size));
  svg.dataset.stop = theme;
  if (label) {
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", label);
  } else {
    svg.setAttribute("aria-hidden", "true");
  }
  const prefix = `t${++copies}-`;
  // The drawings are fixed strings in this file, never user input.
  svg.innerHTML = (Object.hasOwn(STOPS, theme) ? STOPS[theme] : "").replace(/id="/g, `id="${prefix}`).replace(/url\(#/g, `url(#${prefix}`);
  return svg;
}

/** A stop as its own file, for the test. */
export const stopArtFile = (theme) => `<svg xmlns="${SVG_NS}" viewBox="0 0 96 96">${STOPS[theme]}</svg>`;
